from google.oauth2 import service_account
from googleapiclient.discovery import build

SERVICE_ACCOUNT_FILE = '/home/loser/wsl-projects/ageless-impulse-488713-m6-03014b3cddad.json'
PRESENTATION_ID = '1YIfc0YPCiqFFzInkfuhipkh8rC8X66i5VPpqIJS9HOE'
SCOPES = ['https://www.googleapis.com/auth/presentations']

credentials = service_account.Credentials.from_service_account_file(SERVICE_ACCOUNT_FILE, scopes=SCOPES)
service = build('slides', 'v1', credentials=credentials)

# さらに左へ 200,000 EMU 追加シフト（合計 -480,000 EMU 分の位置になる）
SHIFT_EMU = -200_000
FIVE_CHAR_SLIDES = {'gNEW_2', 'gNEW_15'}

pres = service.presentations().get(presentationId=PRESENTATION_ID).execute()

requests = []
for slide in pres.get('slides', []):
    if slide['objectId'] not in FIVE_CHAR_SLIDES:
        continue
    for el in slide.get('pageElements', []):
        if 'shape' not in el or 'text' not in el['shape']:
            continue
        parts = []
        for te in el['shape']['text'].get('textElements', []):
            if 'textRun' in te:
                parts.append(te['textRun'].get('content',''))
        text = ''.join(parts).strip()
        if 'STAFF' in text:
            continue
        eid = el['objectId']
        cur_tx = el['transform']['translateX']
        new_tx = cur_tx + SHIFT_EMU
        requests.append({
            "updatePageElementTransform": {
                "objectId": eid,
                "transform": {
                    "scaleX": el['transform']['scaleX'],
                    "scaleY": el['transform']['scaleY'],
                    "translateX": new_tx,
                    "translateY": el['transform']['translateY'],
                    "unit": "EMU"
                },
                "applyMode": "ABSOLUTE"
            }
        })
        print(f"  {text!r}: tx {cur_tx:.0f} → {new_tx:.0f}")

print(f"\n{len(requests)} 件を実行...")
resp = service.presentations().batchUpdate(
    presentationId=PRESENTATION_ID, body={"requests": requests}
).execute()
print(f"  {len(resp.get('replies',[]))} 件完了 ✅")
